-- Cap nhat mo ta 100 mon an AT-11
-- Chi thay doi cot mo_ta; giu nguyen cac cot khac.

UPDATE mon_an SET mo_ta = 'Món phở nước dùng bánh phở và thịt bò, thường ăn kèm hành, rau thơm và gia vị. Cách nêm nếm và đồ ăn kèm thay đổi theo vùng miền.' WHERE mon_an_id = 1;
UPDATE mon_an SET mo_ta = 'Bún ăn cùng thịt lợn nướng hoặc chả viên nướng, rau sống và nước chấm pha. Đây là món ăn nổi tiếng của Hà Nội.' WHERE mon_an_id = 2;
UPDATE mon_an SET mo_ta = 'Bánh làm từ bột gạo tráng mỏng, thường có nhân thịt và mộc nhĩ; ăn kèm hành phi, rau thơm hoặc chả tùy nơi.' WHERE mon_an_id = 3;
UPDATE mon_an SET mo_ta = 'Món cá được tẩm ướp rồi chế biến, có nhiều biến thể theo địa phương. Cần phân biệt món chả cá nói chung với các phiên bản đặc sản cụ thể.' WHERE mon_an_id = 4;
UPDATE mon_an SET mo_ta = 'Món bún ăn cùng cá và nước dùng; loại cá, cách chế biến và hương vị thay đổi theo địa phương.' WHERE mon_an_id = 5;
UPDATE mon_an SET mo_ta = 'Cơm được làm giòn, thường dùng kèm nước sốt hoặc món ăn mặn. Thành phần và cách phục vụ tùy phiên bản địa phương.' WHERE mon_an_id = 6;
UPDATE mon_an SET mo_ta = 'Món ăn truyền thống vùng núi phía Bắc, thường gắn với văn hóa ẩm thực của các cộng đồng miền núi. Nguyên liệu và cách nấu có thể khác nhau.' WHERE mon_an_id = 7;
UPDATE mon_an SET mo_ta = 'Bánh mì cỡ nhỏ kẹp nhân và thường dùng cùng sốt cay; thành phần cụ thể tùy cơ sở và biến thể địa phương.' WHERE mon_an_id = 8;
UPDATE mon_an SET mo_ta = 'Món bún nước đặc trưng của Huế, thường có nước dùng đậm vị từ xương, sả và mắm ruốc, ăn cùng thịt bò và các thành phần đi kèm.' WHERE mon_an_id = 9;
UPDATE mon_an SET mo_ta = 'Món cơm ăn cùng hến và nhiều thành phần phụ trợ như rau, gia vị, tóp mỡ hoặc bánh tráng tùy cách làm.' WHERE mon_an_id = 10;
UPDATE mon_an SET mo_ta = 'Món mì miền Trung dùng sợi mì bản rộng, lượng nước dùng vừa phải và các thành phần ăn kèm như thịt, tôm, rau, đậu phộng hoặc bánh tráng.' WHERE mon_an_id = 11;
UPDATE mon_an SET mo_ta = 'Món mì gắn với Hội An, thường có sợi mì dày, thịt xá xíu, rau sống và ít nước sốt/nước dùng đậm vị.' WHERE mon_an_id = 12;
UPDATE mon_an SET mo_ta = 'Bánh áp chảo từ bột gạo, thường có màu vàng và nhân tùy vùng; thường ăn cùng rau sống và nước chấm.' WHERE mon_an_id = 13;
UPDATE mon_an SET mo_ta = 'Bún ăn cùng chả cá và nước dùng; món có nhiều biến thể ở các địa phương ven biển.' WHERE mon_an_id = 14;
UPDATE mon_an SET mo_ta = 'Sản phẩm từ bột gạo tạo thành sợi/bánh mảnh, thường ăn cùng thịt, lòng hoặc món mặn và nước chấm tùy địa phương.' WHERE mon_an_id = 15;
UPDATE mon_an SET mo_ta = 'Thịt xay hoặc thịt băm được tẩm ướp, tạo hình rồi nướng; thường ăn kèm rau, bánh tráng và nước chấm tùy biến thể.' WHERE mon_an_id = 16;
UPDATE mon_an SET mo_ta = 'Món bún ăn cùng sứa đã sơ chế và nước dùng; cách chế biến và nguyên liệu đi kèm tùy địa phương.' WHERE mon_an_id = 17;
UPDATE mon_an SET mo_ta = 'Món gỏi sử dụng cá đã được sơ chế theo cách phù hợp, kết hợp gia vị và rau ăn kèm. Cần mô tả rõ loại cá và phương pháp chế biến của từng phiên bản.' WHERE mon_an_id = 18;
UPDATE mon_an SET mo_ta = 'Cơm làm từ hạt gạo tấm, thường ăn cùng sườn nướng, bì, chả, trứng hoặc các món kèm và nước mắm pha.' WHERE mon_an_id = 19;
UPDATE mon_an SET mo_ta = 'Món dùng sợi hủ tiếu, có thể ăn dạng nước hoặc khô với nước dùng/nước sốt và nhiều loại đồ ăn kèm.' WHERE mon_an_id = 20;
UPDATE mon_an SET mo_ta = 'Món nước dùng sợi bánh canh dày, làm từ bột gạo hoặc bột năng tùy loại; phần ăn kèm có thể là cá, cua, thịt hoặc giò.' WHERE mon_an_id = 21;
UPDATE mon_an SET mo_ta = 'Món lẩu có nước dùng nấu từ mắm, thường ăn cùng rau và nhiều loại nguyên liệu như cá, tôm hoặc thịt tùy cách nấu.' WHERE mon_an_id = 22;
UPDATE mon_an SET mo_ta = 'Biến thể bánh xèo miền Tây, thường có vỏ bánh giòn, nhân tùy địa phương và ăn cùng nhiều loại rau sống.' WHERE mon_an_id = 23;
UPDATE mon_an SET mo_ta = 'Món bún nước kèn gắn với ẩm thực miền Tây Nam Bộ; công thức có thể dùng cá và nước dùng nêm gia vị đặc trưng tùy địa phương.' WHERE mon_an_id = 24;
UPDATE mon_an SET mo_ta = 'Bánh nhiều lớp vỏ với phần nhân ngọt; loại nhân và cách làm thay đổi theo sản phẩm và cơ sở chế biến.' WHERE mon_an_id = 25;
UPDATE mon_an SET mo_ta = 'Bánh chiên làm trong khuôn, thường có phần bột và nhân; nguyên liệu và cách ăn kèm tùy phiên bản địa phương.' WHERE mon_an_id = 26;
UPDATE mon_an SET mo_ta = 'Món cháo nấu từ gạo, thường dùng cùng lòng và nội tạng đã chế biến chín, rau thơm và gia vị.' WHERE mon_an_id = 27;
UPDATE mon_an SET mo_ta = 'Cuốn bánh tráng với các thành phần như bún, rau thơm, thịt hoặc tôm tùy phiên bản; thường ăn kèm nước chấm.' WHERE mon_an_id = 28;
UPDATE mon_an SET mo_ta = 'Bánh nhỏ đổ trong khuôn, thường làm từ bột gạo và có nhân tùy cách làm; thường ăn cùng rau sống và nước chấm.' WHERE mon_an_id = 29;
UPDATE mon_an SET mo_ta = 'Cá lóc được nướng nguyên con theo cách dân dã, thường ăn cùng rau và các loại nước chấm hoặc cuốn bánh tráng.' WHERE mon_an_id = 30;
UPDATE mon_an SET mo_ta = 'Xôi nếp có nhiều màu, thường gắn với văn hóa ẩm thực của một số cộng đồng dân tộc miền núi phía Bắc; màu sắc thường được tạo từ nguyên liệu tự nhiên.' WHERE mon_an_id = 31;
UPDATE mon_an SET mo_ta = 'Bánh làm từ hạt tam giác mạch, gắn với ẩm thực vùng cao Hà Giang; cách làm và hình thức có thể khác nhau.' WHERE mon_an_id = 32;
UPDATE mon_an SET mo_ta = 'Bánh có lớp vỏ màu sẫm từ lá gai, thường làm từ bột nếp và có nhân ngọt như đậu xanh, dừa hoặc mè tùy nơi.' WHERE mon_an_id = 33;
UPDATE mon_an SET mo_ta = 'Món bánh làm từ bột gạo hoặc bột khác, có dạng mềm/dẻo; có loại ăn mặn hoặc ngọt tùy vùng.' WHERE mon_an_id = 34;
UPDATE mon_an SET mo_ta = 'Món miến ăn cùng lươn, có thể dùng dạng nước hoặc trộn/khô; cách chế biến và gia vị tùy địa phương.' WHERE mon_an_id = 35;
UPDATE mon_an SET mo_ta = 'Món bún nước thanh, thường có nhiều thành phần thái sợi như thịt gà, trứng và giò, gắn với ẩm thực Hà Nội.' WHERE mon_an_id = 36;
UPDATE mon_an SET mo_ta = 'Món bánh đa đỏ ăn cùng nước dùng cua và các thành phần như rau, chả hoặc topping tùy quán; nổi tiếng ở Hải Phòng.' WHERE mon_an_id = 37;
UPDATE mon_an SET mo_ta = 'Thịt được ướp và lên men theo quy trình phù hợp, thường có vị chua; công thức và cách gói khác nhau theo địa phương.' WHERE mon_an_id = 38;
UPDATE mon_an SET mo_ta = 'Món bún ăn cùng cá rô và nước dùng; cách chế biến cá và rau ăn kèm thay đổi theo địa phương.' WHERE mon_an_id = 39;
UPDATE mon_an SET mo_ta = 'Bánh nhỏ làm từ bột gạo, thường hấp trong chén hoặc khuôn, ăn cùng topping và nước chấm tùy vùng.' WHERE mon_an_id = 40;
UPDATE mon_an SET mo_ta = 'Phở bò có nước dùng ninh từ xương, bánh phở và thịt bò, thường ăn cùng hành, rau thơm và gia vị.' WHERE mon_an_id = 41;
UPDATE mon_an SET mo_ta = 'Bún chả gồm bún tươi, chả thịt lợn nướng, rau sống và nước chấm pha theo khẩu vị.' WHERE mon_an_id = 42;
UPDATE mon_an SET mo_ta = 'Bánh cuốn làm từ lớp bột gạo tráng mỏng, thường có nhân thịt băm và mộc nhĩ, ăn cùng nước chấm.' WHERE mon_an_id = 43;
UPDATE mon_an SET mo_ta = 'Chả cá thường được làm từ cá lọc xương, tẩm ướp gia vị rồi chiên hoặc nướng, dùng kèm rau và nước chấm.' WHERE mon_an_id = 44;
UPDATE mon_an SET mo_ta = 'Bún cá kết hợp bún, cá được chiên hoặc chế biến chín và nước dùng, thường ăn kèm rau thơm.' WHERE mon_an_id = 45;
UPDATE mon_an SET mo_ta = 'Cơm cháy có lớp cơm được làm giòn, thường ăn cùng nước sốt hoặc các món ăn kèm tùy cách chế biến.' WHERE mon_an_id = 46;
UPDATE mon_an SET mo_ta = 'Thắng cố là món ăn truyền thống của vùng núi phía Bắc, thường được chế biến từ thịt và nội tạng gia súc cùng các loại gia vị.' WHERE mon_an_id = 47;
UPDATE mon_an SET mo_ta = 'Bánh mì cay thường là bánh mì nhỏ, nhân pate, có thể ăn kèm tương ớt.' WHERE mon_an_id = 48;
UPDATE mon_an SET mo_ta = 'Bún bò Huế gồm bún, nước dùng đậm vị, thịt bò và các loại rau ăn kèm, thường có hương sả và gia vị đặc trưng.' WHERE mon_an_id = 49;
UPDATE mon_an SET mo_ta = 'Cơm hến gồm cơm hoặc bún ăn cùng hến, rau sống, gia vị, tóp mỡ và nước hến tùy cách phục vụ.' WHERE mon_an_id = 50;
UPDATE mon_an SET mo_ta = 'Mì Quảng gồm sợi mì, nước dùng đậm vị, thịt hoặc hải sản, rau sống, bánh tráng nướng và lạc rang.' WHERE mon_an_id = 51;
UPDATE mon_an SET mo_ta = 'Cao lầu là món mì nổi tiếng của Hội An, thường ăn cùng thịt xá xíu, rau sống và bánh mì chiên giòn.' WHERE mon_an_id = 52;
UPDATE mon_an SET mo_ta = 'Bánh xèo là bánh làm từ bột gạo pha nghệ, đổ giòn với nhân thịt hoặc tôm, thường ăn kèm rau sống và nước chấm.' WHERE mon_an_id = 53;
UPDATE mon_an SET mo_ta = 'Bún chả cá gồm bún, chả cá và nước dùng, thường kết hợp rau thơm cùng gia vị.' WHERE mon_an_id = 54;
UPDATE mon_an SET mo_ta = 'Bánh hỏi là loại bánh làm từ bột gạo thành sợi mảnh, thường ăn cùng thịt nướng, lòng heo hoặc các món mặn.' WHERE mon_an_id = 55;
UPDATE mon_an SET mo_ta = 'Nem nướng gồm thịt được tẩm ướp, nướng chín và ăn cùng rau sống, bánh tráng hoặc nước chấm.' WHERE mon_an_id = 56;
UPDATE mon_an SET mo_ta = 'Bún sứa gồm bún, sứa, nước dùng và rau ăn kèm, thường có vị thanh mát.' WHERE mon_an_id = 57;
UPDATE mon_an SET mo_ta = 'Gỏi cá thường sử dụng cá tươi sơ chế, trộn hoặc ăn cùng rau, gia vị và nước chấm phù hợp từng địa phương.' WHERE mon_an_id = 58;
UPDATE mon_an SET mo_ta = 'Cơm tấm thường gồm cơm tấm ăn cùng sườn nướng, bì, chả trứng và nước mắm pha.' WHERE mon_an_id = 59;
UPDATE mon_an SET mo_ta = 'Hủ tiếu gồm sợi hủ tiếu, nước dùng hoặc nước trộn, thịt hay hải sản và rau ăn kèm.' WHERE mon_an_id = 60;
UPDATE mon_an SET mo_ta = 'Bánh canh gồm sợi bánh canh làm từ bột gạo hoặc bột mì, dùng với nước dùng và các nguyên liệu như thịt, cá hoặc tôm.' WHERE mon_an_id = 61;
UPDATE mon_an SET mo_ta = 'Lẩu mắm có nước lẩu nấu từ mắm, kết hợp cá, tôm, thịt và nhiều loại rau ăn kèm.' WHERE mon_an_id = 62;
UPDATE mon_an SET mo_ta = 'Bánh xèo miền Tây thường có kích thước lớn, vỏ bánh giòn và nhân tôm, thịt cùng giá đỗ, ăn với rau sống.' WHERE mon_an_id = 63;
UPDATE mon_an SET mo_ta = 'Bún nước kèn thường có nước dùng nấu cùng cá và gia vị, kết hợp bún cùng rau ăn kèm.' WHERE mon_an_id = 64;
UPDATE mon_an SET mo_ta = 'Bánh pía là bánh có lớp vỏ nhiều tầng, thường có nhân đậu xanh, sầu riêng và lòng đỏ trứng muối.' WHERE mon_an_id = 65;
UPDATE mon_an SET mo_ta = 'Bánh cống thường gồm lớp bột chiên giòn với nhân đậu xanh, thịt và tôm, ăn kèm rau sống cùng nước chấm.' WHERE mon_an_id = 66;
UPDATE mon_an SET mo_ta = 'Cháo lòng được nấu từ gạo với nước dùng, thường ăn cùng lòng heo, rau thơm và gia vị.' WHERE mon_an_id = 67;
UPDATE mon_an SET mo_ta = 'Gỏi cuốn gồm bánh tráng cuốn rau sống, bún và các nguyên liệu như tôm, thịt, dùng cùng nước chấm.' WHERE mon_an_id = 68;
UPDATE mon_an SET mo_ta = 'Bánh khọt là bánh nhỏ làm từ bột gạo, đổ trong khuôn với nhân tôm hoặc nguyên liệu khác, thường ăn cùng rau sống.' WHERE mon_an_id = 69;
UPDATE mon_an SET mo_ta = 'Cá lóc nướng trui là cá lóc được nướng nguyên con theo cách truyền thống, thường ăn cùng rau sống và bánh tráng.' WHERE mon_an_id = 70;
UPDATE mon_an SET mo_ta = 'Xôi ngũ sắc là xôi nếp được tạo nhiều màu từ nguyên liệu tự nhiên, gắn với văn hóa ẩm thực của một số cộng đồng miền núi phía Bắc.' WHERE mon_an_id = 71;
UPDATE mon_an SET mo_ta = 'Bánh tam giác mạch được làm từ hạt tam giác mạch xay thành bột, chế biến thành bánh đặc trưng ở vùng cao Hà Giang.' WHERE mon_an_id = 72;
UPDATE mon_an SET mo_ta = 'Bánh gai có lớp vỏ bột nếp trộn lá gai, thường có nhân đậu xanh hoặc dừa và được gói bằng lá rồi hấp.' WHERE mon_an_id = 73;
UPDATE mon_an SET mo_ta = 'Bánh đúc được làm từ bột gạo, có thể ăn cùng nước mắm hoặc nhân thịt, mộc nhĩ tùy loại bánh.' WHERE mon_an_id = 74;
UPDATE mon_an SET mo_ta = 'Miến lươn gồm miến và lươn được chế biến chín, ăn cùng nước dùng hoặc dạng trộn với rau thơm.' WHERE mon_an_id = 75;
UPDATE mon_an SET mo_ta = 'Bún thang là món bún nước với nhiều nguyên liệu thái sợi như thịt gà, trứng và giò, dùng cùng nước dùng thanh.' WHERE mon_an_id = 76;
UPDATE mon_an SET mo_ta = 'Bánh đa cua gồm bánh đa, nước dùng cua và các nguyên liệu ăn kèm như rau, chả hoặc tôm tùy cách chế biến.' WHERE mon_an_id = 77;
UPDATE mon_an SET mo_ta = 'Nem chua được làm từ thịt lợn và bì lên men cùng gia vị, có vị chua nhẹ và thường ăn kèm tỏi, ớt.' WHERE mon_an_id = 78;
UPDATE mon_an SET mo_ta = 'Bún cá rô gồm bún, cá rô được chế biến chín và nước dùng, thường ăn cùng rau xanh.' WHERE mon_an_id = 79;
UPDATE mon_an SET mo_ta = 'Bánh bèo làm từ bột gạo hấp trong chén nhỏ, thường ăn cùng nhân tôm, hành phi và nước mắm.' WHERE mon_an_id = 80;
UPDATE mon_an SET mo_ta = 'Bún mọc có nước dùng thanh, kết hợp bún, mọc làm từ thịt xay và các loại rau ăn kèm.' WHERE mon_an_id = 81;
UPDATE mon_an SET mo_ta = 'Xôi xéo thường gồm xôi nếp, đậu xanh nghiền, hành phi và mỡ gà hoặc dầu ăn, tạo nên vị béo bùi đặc trưng.' WHERE mon_an_id = 82;
UPDATE mon_an SET mo_ta = 'Bánh tẻ làm từ bột gạo, thường có nhân thịt băm và mộc nhĩ, được gói bằng lá rồi hấp chín.' WHERE mon_an_id = 83;
UPDATE mon_an SET mo_ta = 'Chả rươi thường kết hợp rươi, trứng, thịt băm, thì là và gia vị, sau đó chiên chín vàng.' WHERE mon_an_id = 84;
UPDATE mon_an SET mo_ta = 'Nem cua bể thường có nhân cua, tôm, thịt và rau củ, được cuốn bằng bánh đa nem rồi chiên vàng.' WHERE mon_an_id = 85;
UPDATE mon_an SET mo_ta = 'Bánh đa trộn kết hợp bánh đa với rau thơm, lạc rang, hành phi và nước trộn; thành phần có thể thay đổi tùy cách chế biến.' WHERE mon_an_id = 86;
UPDATE mon_an SET mo_ta = 'Cháo sườn được nấu từ gạo hoặc bột gạo cùng sườn heo, tạo độ sánh mịn, thường ăn kèm quẩy và gia vị.' WHERE mon_an_id = 87;
UPDATE mon_an SET mo_ta = 'Bún đậu mắm tôm gồm bún, đậu phụ chiên, mắm tôm và các món ăn kèm như rau thơm, chả hoặc thịt luộc.' WHERE mon_an_id = 88;
UPDATE mon_an SET mo_ta = 'Bánh tôm thường gồm tôm và bột được chiên giòn, có thể ăn kèm rau sống cùng nước chấm chua ngọt.' WHERE mon_an_id = 89;
UPDATE mon_an SET mo_ta = 'Nem nắm thường được làm từ thịt lợn, bì lợn thái nhỏ, thính gạo và gia vị, ăn kèm lá sung hoặc rau thơm.' WHERE mon_an_id = 90;
UPDATE mon_an SET mo_ta = 'Bánh căn được làm từ bột gạo, đổ vào khuôn nhỏ và nướng chín; nhân có thể gồm trứng, tôm hoặc thịt.' WHERE mon_an_id = 91;
UPDATE mon_an SET mo_ta = 'Bánh ít lá gai được làm từ bột nếp trộn lá gai, thường có nhân đậu xanh hoặc dừa, gói bằng lá rồi hấp chín.' WHERE mon_an_id = 92;
UPDATE mon_an SET mo_ta = 'Mực một nắng là mực tươi được sơ chế và phơi qua một lượt nắng, thường được nướng hoặc chế biến để giữ vị ngọt tự nhiên.' WHERE mon_an_id = 93;
UPDATE mon_an SET mo_ta = 'Bò né thường gồm thịt bò áp chảo cùng trứng, pate hoặc xúc xích, dùng nóng với bánh mì và nước sốt.' WHERE mon_an_id = 94;
UPDATE mon_an SET mo_ta = 'Chả ram tôm đất gồm tôm đất và các nguyên liệu làm nhân được cuốn trong bánh tráng, sau đó chiên giòn.' WHERE mon_an_id = 95;
UPDATE mon_an SET mo_ta = 'Bánh hỏi lòng heo kết hợp bánh hỏi làm từ bột gạo với lòng heo, rau sống và nước chấm.' WHERE mon_an_id = 96;
UPDATE mon_an SET mo_ta = 'Cơm gà gồm cơm ăn cùng thịt gà luộc hoặc chiên, thường có rau ăn kèm và nước chấm riêng.' WHERE mon_an_id = 97;
UPDATE mon_an SET mo_ta = 'Mì Quảng gà gồm sợi mì, thịt gà, nước dùng đậm vị, rau sống, bánh tráng nướng và lạc rang.' WHERE mon_an_id = 98;
UPDATE mon_an SET mo_ta = 'Bánh bò thốt nốt sử dụng đường thốt nốt để tạo vị ngọt và màu sắc đặc trưng, có kết cấu mềm xốp.' WHERE mon_an_id = 99;
UPDATE mon_an SET mo_ta = 'Bún thịt nướng gồm bún tươi, thịt ướp gia vị rồi nướng, rau sống, đồ chua và nước mắm pha.' WHERE mon_an_id = 100;
